-- Phase 3a batch 3: remaining 22 infusion/toast/bloom/custard steps

INSERT INTO step_translations (instruction_en, instruction_fr, instruction_es, instruction_de, instruction_pt, hint_en, hint_fr, hint_es, hint_de, hint_pt) VALUES

-- 26. blackberry-sage-honey
  ('Warm the milk and cream with the sage leaves over medium-low heat until steaming (do not boil). Remove from heat, cover, and steep for 15 minutes. Strain out the sage, then whisk in the sugar, honey, vanilla, and blackberry puree. Cool completely.',
   'Faire chauffer le lait et la crème avec les feuilles de sauge à feu moyen-doux jusqu''à frémissement (ne pas faire bouillir). Retirer du feu, couvrir et laisser infuser 15 minutes. Filtrer pour retirer la sauge, puis incorporer au fouet le sucre, le miel, la vanille et la purée de mûres. Laisser refroidir complètement.',
   'Calentar la leche y la nata con las hojas de salvia a fuego medio-bajo hasta que humee (no hervir). Retirar del fuego, tapar e infusionar durante 15 minutos. Colar para retirar la salvia, luego incorporar con varillas el azúcar, la miel, la vainilla y el puré de moras. Dejar enfriar completamente.',
   'Milch und Sahne mit den Salbeiblättern bei mittlerer bis niedriger Hitze erwärmen, bis es dampft (nicht kochen). Vom Herd nehmen, abdecken und 15 Minuten ziehen lassen. Salbei abseihen, dann Zucker, Honig, Vanille und Brombeerpüree einrühren. Vollständig abkühlen lassen.',
   'Aqueça o leite e o creme de leite com as folhas de sálvia em fogo médio-baixo até soltar vapor (não ferver). Retire do fogo, tampe e deixe em infusão por 15 minutos. Coe para retirar a sálvia, depois misture com fouet o açúcar, o mel, a baunilha e o purê de amora. Deixe esfriar completamente.',
   'Sage is earthy and can easily overpower fruit — keep the infusion to exactly 15 minutes and pull the leaves out.',
   'La sauge est terreuse et peut facilement dominer les fruits — limitez l''infusion à exactement 15 minutes et retirez les feuilles.',
   'La salvia es terrosa y puede dominar la fruta fácilmente — limita la infusión a exactamente 15 minutos y retira las hojas.',
   'Salbei ist erdig und kann Früchte leicht überdecken — die Infusion auf genau 15 Minuten beschränken und die Blätter herausnehmen.',
   'A sálvia é terrosa e pode facilmente dominar a fruta — mantenha a infusão em exatamente 15 minutos e retire as folhas.'),

-- 27. lavender-blueberry-cream
  ('Warm the milk and cream with the lavender buds over medium-low heat until steaming (do not boil). Remove from heat, cover, and steep for 10 minutes. Strain out the lavender, then whisk in the sugar, vanilla, and blueberry puree. Cool completely.',
   'Faire chauffer le lait et la crème avec les boutons de lavande à feu moyen-doux jusqu''à frémissement (ne pas faire bouillir). Retirer du feu, couvrir et laisser infuser 10 minutes. Filtrer pour retirer la lavande, puis incorporer au fouet le sucre, la vanille et la purée de myrtilles. Laisser refroidir complètement.',
   'Calentar la leche y la nata con los capullos de lavanda a fuego medio-bajo hasta que humee (no hervir). Retirar del fuego, tapar e infusionar durante 10 minutos. Colar para retirar la lavanda, luego incorporar con varillas el azúcar, la vainilla y el puré de arándanos. Dejar enfriar completamente.',
   'Milch und Sahne mit den Lavendelblüten bei mittlerer bis niedriger Hitze erwärmen, bis es dampft (nicht kochen). Vom Herd nehmen, abdecken und 10 Minuten ziehen lassen. Lavendel abseihen, dann Zucker, Vanille und Heidelbeerpüree einrühren. Vollständig abkühlen lassen.',
   'Aqueça o leite e o creme de leite com os botões de lavanda em fogo médio-baixo até soltar vapor (não ferver). Retire do fogo, tampe e deixe em infusão por 10 minutos. Coe para retirar a lavanda, depois misture com fouet o açúcar, a baunilha e o purê de mirtilo. Deixe esfriar completamente.',
   '10 minutes of steeping is the sweet spot — any longer and lavender goes soapy. Blueberry complements the florals perfectly.',
   '10 minutes d''infusion sont idéales — au-delà, la lavande devient savonneuse. La myrtille complète parfaitement les notes florales.',
   '10 minutos de infusión son el punto ideal — más tiempo y la lavanda se vuelve jabonosa. El arándano complementa perfectamente las notas florales.',
   '10 Minuten Ziehzeit sind ideal — länger, und der Lavendel wird seifig. Heidelbeere ergänzt die floralen Noten perfekt.',
   '10 minutos de infusão são o ponto ideal — mais do que isso e a lavanda fica sabonosa. O mirtilo complementa perfeitamente as notas florais.'),

-- 28. lavender-honey-vanilla
  ('Warm the milk and honey with the lavender buds over medium-low heat until steaming (do not boil). Remove from heat, cover, and steep for 10 minutes. Strain out the lavender, then whisk in the cream, sugar, and vanilla. Cool completely before pouring into the pint.',
   'Faire chauffer le lait et le miel avec les boutons de lavande à feu moyen-doux jusqu''à frémissement (ne pas faire bouillir). Retirer du feu, couvrir et laisser infuser 10 minutes. Filtrer pour retirer la lavande, puis incorporer au fouet la crème, le sucre et la vanille. Laisser refroidir complètement avant de verser dans le pot.',
   'Calentar la leche y la miel con los capullos de lavanda a fuego medio-bajo hasta que humee (no hervir). Retirar del fuego, tapar e infusionar durante 10 minutos. Colar para retirar la lavanda, luego incorporar con varillas la nata, el azúcar y la vainilla. Dejar enfriar completamente antes de verter en el recipiente.',
   'Milch und Honig mit den Lavendelblüten bei mittlerer bis niedriger Hitze erwärmen, bis es dampft (nicht kochen). Vom Herd nehmen, abdecken und 10 Minuten ziehen lassen. Lavendel abseihen, dann Sahne, Zucker und Vanille einrühren. Vor dem Einfüllen in den Becher vollständig abkühlen lassen.',
   'Aqueça o leite e o mel com os botões de lavanda em fogo médio-baixo até soltar vapor (não ferver). Retire do fogo, tampe e deixe em infusão por 10 minutos. Coe para retirar a lavanda, depois misture com fouet o creme de leite, o açúcar e a baunilha. Deixe esfriar completamente antes de despejar no pote.',
   'Honey dissolves faster into warm milk than cold — let it come to steaming with the milk to save whisking later.',
   'Le miel se dissout plus vite dans le lait chaud que froid — laissez-le monter en température avec le lait pour économiser un fouettage ultérieur.',
   'La miel se disuelve más rápido en leche tibia que fría — deja que suba de temperatura con la leche para ahorrarte batir después.',
   'Honig löst sich in warmer Milch schneller als in kalter — zusammen mit der Milch erwärmen, um späteres Verrühren zu sparen.',
   'O mel dissolve mais rápido em leite quente do que frio — deixe aquecer junto com o leite para poupar trabalho depois.'),

-- 29. lavender-lemon-cream
  ('Warm the milk in a small saucepan with the lavender buds over medium-low heat until steaming (do not boil). Remove from heat, cover, and let steep for 10 minutes. Strain out the lavender, then whisk in the cream, sugar, vanilla, and lemon juice. Cool completely before pouring into the pint.',
   'Faire chauffer le lait dans une petite casserole avec les boutons de lavande à feu moyen-doux jusqu''à frémissement (ne pas faire bouillir). Retirer du feu, couvrir et laisser infuser 10 minutes. Filtrer pour retirer la lavande, puis incorporer au fouet la crème, le sucre, la vanille et le jus de citron. Laisser refroidir complètement avant de verser dans le pot.',
   'Calentar la leche en un cazo pequeño con los capullos de lavanda a fuego medio-bajo hasta que humee (no hervir). Retirar del fuego, tapar y dejar infusionar durante 10 minutos. Colar para retirar la lavanda, luego incorporar con varillas la nata, el azúcar, la vainilla y el jugo de limón. Dejar enfriar completamente antes de verter en el recipiente.',
   'Milch in einem kleinen Topf mit den Lavendelblüten bei mittlerer bis niedriger Hitze erwärmen, bis es dampft (nicht kochen). Vom Herd nehmen, abdecken und 10 Minuten ziehen lassen. Lavendel abseihen, dann Sahne, Zucker, Vanille und Zitronensaft einrühren. Vor dem Einfüllen in den Becher vollständig abkühlen lassen.',
   'Aqueça o leite numa panelinha com os botões de lavanda em fogo médio-baixo até soltar vapor (não ferver). Retire do fogo, tampe e deixe em infusão por 10 minutos. Coe para retirar a lavanda, depois misture com fouet o creme de leite, o açúcar, a baunilha e o suco de limão. Deixe esfriar completamente antes de despejar no pote.',
   'Lavender infusion should taste floral but never soapy. 10 minutes is the sweet spot — any longer and it turns perfumey.',
   'L''infusion de lavande doit avoir un goût floral mais jamais savonneux. 10 minutes sont idéales — au-delà, elle devient parfumée.',
   'La infusión de lavanda debe tener sabor floral pero nunca jabonoso. 10 minutos es el punto ideal — más tiempo y se vuelve perfumada.',
   'Lavendelinfusion sollte floral, aber nie seifig schmecken. 10 Minuten sind ideal — länger, und sie wird parfümig.',
   'A infusão de lavanda deve ter sabor floral mas nunca saboneto. 10 minutos é o ponto ideal — mais do que isso e fica perfumada.'),

-- 30. strawberry-basil-gelato
  ('Gently warm the milk and cream with the basil leaves in a small saucepan over medium-low heat until steaming (do not boil). Remove from heat, cover, and steep for 15 minutes. Strain out the basil, then whisk the strawberry puree into the infused dairy. Cool completely before pouring into the pint.',
   'Faire chauffer doucement le lait et la crème avec les feuilles de basilic dans une petite casserole à feu moyen-doux jusqu''à frémissement (ne pas faire bouillir). Retirer du feu, couvrir et laisser infuser 15 minutes. Filtrer pour retirer le basilic, puis incorporer au fouet la purée de fraise dans le mélange laitier infusé. Laisser refroidir complètement avant de verser dans le pot.',
   'Calentar suavemente la leche y la nata con las hojas de albahaca en un cazo pequeño a fuego medio-bajo hasta que humee (no hervir). Retirar del fuego, tapar e infusionar durante 15 minutos. Colar para retirar la albahaca, luego incorporar con varillas el puré de fresa a la mezcla láctea infusionada. Dejar enfriar completamente antes de verter en el recipiente.',
   'Milch und Sahne mit den Basilikumblättern in einem kleinen Topf bei mittlerer bis niedriger Hitze sanft erwärmen, bis es dampft (nicht kochen). Vom Herd nehmen, abdecken und 15 Minuten ziehen lassen. Basilikum abseihen, dann Erdbeerpüree in die infundierte Milchmischung einrühren. Vor dem Einfüllen in den Becher vollständig abkühlen lassen.',
   'Aqueça suavemente o leite e o creme de leite com as folhas de manjericão numa panelinha em fogo médio-baixo até soltar vapor (não ferver). Retire do fogo, tampe e deixe em infusão por 15 minutos. Coe para retirar o manjericão, depois misture com fouet o purê de morango na mistura láctea infusionada. Deixe esfriar completamente antes de despejar no pote.',
   'Strawberry and basil are a classic summer pairing; warm-dairy infusion pulls the aromatic oils out of the leaves the way cold blending cannot.',
   'Fraise et basilic forment un duo estival classique ; l''infusion dans les produits laitiers chauds extrait des feuilles les huiles aromatiques qu''un mixage à froid ne peut pas capter.',
   'Fresa y albahaca son un maridaje clásico de verano; la infusión en lácteos tibios extrae de las hojas los aceites aromáticos que el licuado frío no puede capturar.',
   'Erdbeere und Basilikum sind eine klassische Sommerkombination; die Warmmilch-Infusion zieht aromatische Öle aus den Blättern, die kaltes Mixen nicht erfasst.',
   'Morango e manjericão são uma combinação clássica de verão; a infusão em laticínios quentes extrai das folhas os óleos aromáticos que a mistura fria não captura.'),

-- 31. brown-butter-sage (infuse)
  ('Brown the butter and infuse the sage: melt butter in a small saucepan over medium heat, swirling until it turns amber and smells nutty (3–4 minutes). Remove from heat, drop in sage leaves, and let steep 10 minutes. Strain out the sage.',
   'Faire dorer le beurre et infuser la sauge : faire fondre le beurre dans une petite casserole à feu moyen, en remuant par mouvements circulaires jusqu''à ce qu''il prenne une couleur ambrée et dégage une odeur de noisette (3 à 4 minutes). Retirer du feu, ajouter les feuilles de sauge et laisser infuser 10 minutes. Filtrer pour retirer la sauge.',
   'Dorar la mantequilla e infusionar la salvia: derretir la mantequilla en un cazo pequeño a fuego medio, moviendo con movimientos circulares hasta que tome un color ámbar y huela a nuez (3–4 minutos). Retirar del fuego, añadir las hojas de salvia y dejar infusionar 10 minutos. Colar para retirar la salvia.',
   'Die Butter bräunen und den Salbei einziehen lassen: Butter in einem kleinen Topf bei mittlerer Hitze schmelzen, dabei schwenken, bis sie bernsteinfarben ist und nussig duftet (3–4 Minuten). Vom Herd nehmen, die Salbeiblätter hineingeben und 10 Minuten ziehen lassen. Den Salbei abseihen.',
   'Dourar a manteiga e infundir a sálvia: derreta a manteiga numa panelinha em fogo médio, girando a panela até ficar âmbar e com aroma de noz (3–4 minutos). Retire do fogo, adicione as folhas de sálvia e deixe em infusão por 10 minutos. Coe para retirar a sálvia.',
   'Brown butter burns fast — pull it off heat the instant it smells like hazelnuts. Residual heat will darken it another shade.',
   'Le beurre noisette brûle vite — retirez-le du feu dès qu''il sent la noisette. La chaleur résiduelle le foncera encore d''une nuance.',
   'La mantequilla noisette se quema rápido — retírala del fuego en cuanto huela a avellana. El calor residual la oscurecerá un tono más.',
   'Braune Butter verbrennt schnell — vom Herd nehmen, sobald sie nach Haselnüssen duftet. Die Restwärme verdunkelt sie noch um eine Nuance.',
   'Manteiga noisette queima rápido — tire do fogo no instante em que cheirar a avelãs. O calor residual ainda vai escurecê-la mais um tom.'),

-- 32. crema-gelato custard
  ('Make the custard: whisk egg yolks with sugar in a bowl. Warm milk and cream in a saucepan until steaming, then temper into yolks by whisking in a slow stream. Return to saucepan and cook over low heat, stirring, until it coats the back of a spoon (170–175°F / 77–79°C). Strain and cool completely.',
   'Préparer la crème anglaise : fouetter les jaunes d''œufs avec le sucre dans un bol. Faire chauffer le lait et la crème dans une casserole jusqu''à frémissement, puis tempérer les jaunes en versant le mélange en filet tout en fouettant. Remettre dans la casserole et faire cuire à feu doux, en remuant, jusqu''à ce que la crème nappe le dos d''une cuillère (77–79°C / 170–175°F). Filtrer et laisser refroidir complètement.',
   'Preparar la natilla (crème anglaise): batir las yemas con el azúcar en un bol. Calentar la leche y la nata en un cazo hasta que humee, luego atemperar las yemas vertiendo la mezcla en hilo fino mientras se bate. Volver al cazo y cocinar a fuego lento, removiendo, hasta que la crema cubra el dorso de una cuchara (77–79°C / 170–175°F). Colar y dejar enfriar completamente.',
   'Die Crème anglaise zubereiten: Eigelbe mit Zucker in einer Schüssel verrühren. Milch und Sahne in einem Topf bis zum Dampfen erwärmen, dann langsam unter ständigem Rühren zu den Eigelben gießen, um sie zu temperieren. Zurück in den Topf geben und bei niedriger Hitze unter Rühren kochen, bis die Masse einen Kochlöffelrücken überzieht (77–79°C / 170–175°F). Abseihen und vollständig abkühlen lassen.',
   'Prepare o creme inglês: bata as gemas com o açúcar numa tigela. Aqueça o leite e o creme de leite numa panela até soltar vapor, depois tempere as gemas despejando o líquido em fio fino enquanto bate com fouet. Volte para a panela e cozinhe em fogo baixo, mexendo, até o creme cobrir o dorso de uma colher (77–79°C / 170–175°F). Coe e deixe esfriar completamente.',
   'Do not boil — egg yolks curdle above 180°F. Pull off heat the moment the custard coats the spoon.',
   'Ne pas faire bouillir — les jaunes d''œufs coagulent au-dessus de 82°C. Retirer du feu dès que la crème nappe la cuillère.',
   'No hervir — las yemas se cuajan por encima de 82°C. Retirar del fuego en cuanto la crema cubra la cuchara.',
   'Nicht kochen — Eigelbe gerinnen über 82°C. Vom Herd nehmen, sobald die Masse den Löffel überzieht.',
   'Não ferva — as gemas talham acima de 82°C. Tire do fogo no instante em que o creme cobrir a colher.'),

-- 33. zabaglione custard
  ('Make the zabaglione custard: whisk egg yolks with sugar in a heatproof bowl set over simmering water. Slowly drizzle in Marsala wine while whisking constantly. Whisk for 5–7 minutes until the mixture triples in volume and holds a ribbon. Remove from heat, whisk in warm milk and cream, and cool completely.',
   'Préparer la crème zabaglione : fouetter les jaunes d''œufs avec le sucre dans un bol résistant à la chaleur placé au-dessus d''une casserole d''eau frémissante (bain-marie). Verser le vin de Marsala en filet tout en fouettant sans arrêt. Fouetter pendant 5 à 7 minutes jusqu''à ce que le mélange triple de volume et forme un ruban. Retirer du feu, incorporer au fouet le lait et la crème chauds, puis laisser refroidir complètement.',
   'Preparar la crema zabaglione: batir las yemas con el azúcar en un bol resistente al calor colocado sobre una cacerola con agua a fuego suave (al baño maría). Añadir el vino de Marsala en hilo fino mientras se bate sin parar. Batir durante 5–7 minutos hasta que la mezcla triplique su volumen y forme una cinta. Retirar del fuego, incorporar con varillas la leche y la nata tibias, y dejar enfriar completamente.',
   'Die Zabaglione-Creme zubereiten: Eigelbe mit Zucker in einer hitzefesten Schüssel über einem Topf mit köchelndem Wasser (Wasserbad) verrühren. Marsala-Wein langsam einfließen lassen, dabei ununterbrochen schlagen. 5–7 Minuten schlagen, bis die Masse ihr Volumen verdreifacht und einen Band bildet. Vom Herd nehmen, warme Milch und Sahne einrühren und vollständig abkühlen lassen.',
   'Prepare o creme zabaglione: bata as gemas com o açúcar numa tigela resistente ao calor posicionada sobre uma panela com água em fervura branda (banho-maria). Adicione o vinho Marsala em fio fino enquanto bate sem parar. Bata por 5–7 minutos até a mistura triplicar de volume e formar uma fita. Retire do fogo, misture com fouet o leite e o creme de leite mornos, e deixe esfriar completamente.',
   'Traditional zabaglione is a warm Italian custard with Marsala — don''t rush the whisking or it will be thin. The ribbon stage means the mixture falls from the whisk in a slow, thick stream.',
   'Le zabaglione traditionnel est une crème italienne chaude au Marsala — ne précipitez pas le fouettage, sinon elle sera liquide. Le stade du ruban signifie que le mélange tombe du fouet en un filet épais et lent.',
   'El zabaglione tradicional es una crema italiana caliente con Marsala — no aceleres el batido o quedará líquida. El punto de cinta significa que la mezcla cae del batidor en hilo grueso y lento.',
   'Traditionelle Zabaglione ist eine warme italienische Creme mit Marsala — beim Schlagen nicht hetzen, sonst wird sie dünn. Das Bandstadium bedeutet, dass die Masse in einem langsamen, dicken Strahl vom Schneebesen fällt.',
   'O zabaglione tradicional é um creme italiano quente com Marsala — não apresse o batimento ou ficará ralo. O ponto de fita significa que a mistura cai do fouet em fio grosso e lento.'),

-- 34. toast rolled oats (toasted-oat-honey)
  ('Toast the oats: spread rolled oats on a dry skillet over medium heat, stirring frequently, for 4–5 minutes until fragrant and golden. Transfer to a plate to cool completely before adding as a mix-in.',
   'Griller les flocons d''avoine : étaler les flocons d''avoine dans une poêle sèche à feu moyen, en remuant fréquemment, pendant 4 à 5 minutes jusqu''à ce qu''ils soient parfumés et dorés. Transférer sur une assiette et laisser refroidir complètement avant de les ajouter en mix-in.',
   'Tostar los copos de avena: extender los copos de avena en una sartén seca a fuego medio, removiendo con frecuencia, durante 4–5 minutos hasta que estén aromáticos y dorados. Transferir a un plato y dejar enfriar completamente antes de añadirlos como mix-in.',
   'Die Haferflocken rösten: Haferflocken in einer trockenen Pfanne bei mittlerer Hitze verteilen und häufig umrühren, 4–5 Minuten, bis sie duftend und goldbraun sind. Zum vollständigen Abkühlen auf einen Teller geben, bevor sie als Mix-In hinzugefügt werden.',
   'Torre a aveia em flocos: espalhe a aveia em flocos numa frigideira seca em fogo médio, mexendo com frequência, por 4–5 minutos até ficar aromática e dourada. Transfira para um prato e deixe esfriar completamente antes de adicioná-la como mix-in.',
   'Toasted oats give this flavor a warm, granola-like depth that plain oats cannot. Do not skip — untoasted oats go soggy in the pint.',
   'Les flocons d''avoine grillés donnent à ce parfum une profondeur chaleureuse, façon granola, que les flocons nature ne peuvent pas offrir. À ne pas sauter — les flocons non grillés ramollissent dans le pot.',
   'Los copos de avena tostados dan a este sabor una profundidad cálida, tipo granola, que los copos sin tostar no pueden aportar. No saltes este paso — los copos sin tostar se ablandan en el recipiente.',
   'Geröstete Haferflocken geben diesem Geschmack eine warme, granolaartige Tiefe, die ungeröstete nicht liefern können. Nicht überspringen — ungeröstete Haferflocken werden im Becher matschig.',
   'Aveia torrada dá a esse sabor uma profundidade quente, tipo granola, que a aveia sem torrar não oferece. Não pule — aveia não torrada fica mole no pote.'),

-- 35. toast almonds (roasted-almond-fudge)
  ('Toast the almonds: spread sliced almonds on a dry skillet over medium heat, stirring constantly, until golden and fragrant (3 minutes). Transfer to a plate to cool.',
   'Griller les amandes : étaler les amandes effilées dans une poêle sèche à feu moyen, en remuant sans arrêt, jusqu''à ce qu''elles soient dorées et parfumées (3 minutes). Transférer sur une assiette pour refroidir.',
   'Tostar las almendras: extender las almendras laminadas en una sartén seca a fuego medio, removiendo constantemente, hasta que estén doradas y aromáticas (3 minutos). Transferir a un plato para enfriar.',
   'Die Mandeln rösten: gehobelte Mandeln in einer trockenen Pfanne bei mittlerer Hitze verteilen und ständig umrühren, bis sie goldbraun und duftend sind (3 Minuten). Zum Abkühlen auf einen Teller geben.',
   'Torre as amêndoas: espalhe as amêndoas fatiadas numa frigideira seca em fogo médio, mexendo sem parar, até ficarem douradas e aromáticas (3 minutos). Transfira para um prato para esfriar.',
   'Toasted almonds deepen the "roasted" flavor the title promises.',
   'Les amandes grillées approfondissent la saveur « rôtie » que le titre promet.',
   'Las almendras tostadas intensifican el sabor "asado" que promete el título.',
   'Geröstete Mandeln vertiefen den "roasted"-Geschmack, den der Titel verspricht.',
   'Amêndoas torradas intensificam o sabor "torrado" que o título promete.'),

-- 36. toast almonds (toasted-almond-coconut)
  ('Toast the almonds: spread sliced almonds in a dry skillet over medium heat, stirring constantly, 3–4 minutes until golden and fragrant. Cool before adding as mix-in.',
   'Griller les amandes : étaler les amandes effilées dans une poêle sèche à feu moyen, en remuant sans arrêt, 3 à 4 minutes jusqu''à ce qu''elles soient dorées et parfumées. Laisser refroidir avant de les ajouter en mix-in.',
   'Tostar las almendras: extender las almendras laminadas en una sartén seca a fuego medio, removiendo constantemente, 3–4 minutos hasta que estén doradas y aromáticas. Enfriar antes de añadir como mix-in.',
   'Die Mandeln rösten: gehobelte Mandeln in einer trockenen Pfanne bei mittlerer Hitze verteilen und ständig umrühren, 3–4 Minuten, bis sie goldbraun und duftend sind. Vor dem Hinzufügen als Mix-In abkühlen lassen.',
   'Torre as amêndoas: espalhe as amêndoas fatiadas numa frigideira seca em fogo médio, mexendo sem parar, por 3–4 minutos até ficarem douradas e aromáticas. Esfrie antes de adicionar como mix-in.',
   'Toasted almonds pair beautifully with coconut for an Almond Joy-adjacent flavor.',
   'Les amandes grillées se marient à merveille avec la noix de coco pour une saveur proche de l''Almond Joy.',
   'Las almendras tostadas maridan de maravilla con el coco para un sabor cercano al Almond Joy.',
   'Geröstete Mandeln harmonieren wunderbar mit Kokos für einen Geschmack in der Nähe von Almond Joy.',
   'Amêndoas torradas combinam perfeitamente com o coco para um sabor próximo ao Almond Joy.'),

-- 37. toast almonds (toasted-almond-honey)
  ('Toast the almonds: spread sliced almonds in a dry skillet over medium heat, stirring constantly, for 3–4 minutes until golden and fragrant. Transfer to a plate to cool completely.',
   'Griller les amandes : étaler les amandes effilées dans une poêle sèche à feu moyen, en remuant sans arrêt, pendant 3 à 4 minutes jusqu''à ce qu''elles soient dorées et parfumées. Transférer sur une assiette et laisser refroidir complètement.',
   'Tostar las almendras: extender las almendras laminadas en una sartén seca a fuego medio, removiendo constantemente, durante 3–4 minutos hasta que estén doradas y aromáticas. Transferir a un plato y dejar enfriar completamente.',
   'Die Mandeln rösten: gehobelte Mandeln in einer trockenen Pfanne bei mittlerer Hitze verteilen und ständig umrühren, 3–4 Minuten, bis sie goldbraun und duftend sind. Zum vollständigen Abkühlen auf einen Teller geben.',
   'Torre as amêndoas: espalhe as amêndoas fatiadas numa frigideira seca em fogo médio, mexendo sem parar, por 3–4 minutos até ficarem douradas e aromáticas. Transfira para um prato e deixe esfriar completamente.',
   'Sliced almonds go from golden to burnt in 30 seconds. Pull them off heat slightly early — residual heat keeps toasting them on the plate.',
   'Les amandes effilées passent du doré au brûlé en 30 secondes. Retirez-les du feu un peu tôt — la chaleur résiduelle continue de les griller dans l''assiette.',
   'Las almendras laminadas pasan de doradas a quemadas en 30 segundos. Retíralas del fuego un poco antes — el calor residual sigue tostándolas en el plato.',
   'Gehobelte Mandeln werden in 30 Sekunden von goldbraun zu verbrannt. Etwas früher vom Herd nehmen — die Restwärme röstet sie auf dem Teller weiter.',
   'Amêndoas fatiadas passam de douradas para queimadas em 30 segundos. Tire do fogo um pouco antes — o calor residual continua torrando-as no prato.'),

-- 38. toast sesame (toasted-sesame-honey)
  ('Toast the sesame seeds: place sesame seeds in a dry skillet over medium heat. Stir constantly for 2–3 minutes until fragrant and golden. Transfer immediately to a plate to stop the cooking and cool.',
   'Griller les graines de sésame : placer les graines de sésame dans une poêle sèche à feu moyen. Remuer sans arrêt pendant 2 à 3 minutes jusqu''à ce qu''elles soient parfumées et dorées. Transférer immédiatement sur une assiette pour arrêter la cuisson et laisser refroidir.',
   'Tostar las semillas de sésamo: colocar las semillas de sésamo en una sartén seca a fuego medio. Remover constantemente durante 2–3 minutos hasta que estén aromáticas y doradas. Transferir inmediatamente a un plato para detener la cocción y enfriar.',
   'Die Sesamsamen rösten: Sesamsamen in einer trockenen Pfanne bei mittlerer Hitze geben. 2–3 Minuten ständig umrühren, bis sie duftend und goldbraun sind. Sofort auf einen Teller geben, um den Garvorgang zu stoppen, und abkühlen lassen.',
   'Torre as sementes de gergelim: coloque as sementes de gergelim numa frigideira seca em fogo médio. Mexa sem parar por 2–3 minutos até ficarem aromáticas e douradas. Transfira imediatamente para um prato para interromper o cozimento e esfriar.',
   'Sesame seeds burn in seconds once they colour. Pull them off heat when they''re a shade lighter than you want — they keep cooking on the plate.',
   'Les graines de sésame brûlent en quelques secondes dès qu''elles commencent à colorer. Retirez-les du feu quand elles sont une nuance plus claires que voulu — elles continuent de cuire dans l''assiette.',
   'Las semillas de sésamo se queman en segundos una vez empiezan a dorar. Retíralas del fuego cuando estén un tono más claras que lo deseado — siguen cocinándose en el plato.',
   'Sesamsamen verbrennen in Sekunden, sobald sie Farbe annehmen. Vom Herd nehmen, wenn sie einen Farbton heller sind als gewünscht — sie garen auf dem Teller weiter.',
   'As sementes de gergelim queimam em segundos assim que começam a colorir. Tire do fogo quando estiverem um tom mais claras do que você quer — elas continuam cozinhando no prato.'),

-- 39. toast sesame (toasted-sesame alt)
  ('Toast the sesame seeds: in a dry skillet over medium heat, stir sesame seeds constantly for 2–3 minutes until fragrant and pale gold. Cool on a plate before using as mix-in.',
   'Griller les graines de sésame : dans une poêle sèche à feu moyen, remuer les graines de sésame sans arrêt pendant 2 à 3 minutes jusqu''à ce qu''elles soient parfumées et d''un doré pâle. Laisser refroidir sur une assiette avant de les utiliser en mix-in.',
   'Tostar las semillas de sésamo: en una sartén seca a fuego medio, remover las semillas de sésamo constantemente durante 2–3 minutos hasta que estén aromáticas y de color dorado pálido. Enfriar en un plato antes de usar como mix-in.',
   'Die Sesamsamen rösten: In einer trockenen Pfanne bei mittlerer Hitze Sesamsamen 2–3 Minuten ständig umrühren, bis sie duftend und hellgolden sind. Vor der Verwendung als Mix-In auf einem Teller abkühlen lassen.',
   'Torre as sementes de gergelim: numa frigideira seca em fogo médio, mexa as sementes de gergelim sem parar por 2–3 minutos até ficarem aromáticas e douradas claras. Esfrie num prato antes de usar como mix-in.',
   'Sesame seeds burn in seconds once they color. Pull early; residual heat continues toasting.',
   'Les graines de sésame brûlent en quelques secondes dès qu''elles commencent à colorer. Retirez-les tôt ; la chaleur résiduelle continue de les griller.',
   'Las semillas de sésamo se queman en segundos una vez empiezan a dorar. Retíralas pronto; el calor residual sigue tostándolas.',
   'Sesamsamen verbrennen in Sekunden, sobald sie Farbe annehmen. Früh vom Herd nehmen; die Restwärme röstet weiter.',
   'As sementes de gergelim queimam em segundos assim que começam a colorir. Tire cedo do fogo; o calor residual continua torrando.'),

-- 40. toast rolled oats (brown-sugar version)
  ('Toast the oats: spread rolled oats in a dry skillet over medium heat, stirring frequently, 4–5 minutes until fragrant and golden. Cool before adding as a mix-in.',
   'Griller les flocons d''avoine : étaler les flocons d''avoine dans une poêle sèche à feu moyen, en remuant fréquemment, 4 à 5 minutes jusqu''à ce qu''ils soient parfumés et dorés. Laisser refroidir avant de les ajouter en mix-in.',
   'Tostar los copos de avena: extender los copos de avena en una sartén seca a fuego medio, removiendo con frecuencia, 4–5 minutos hasta que estén aromáticos y dorados. Enfriar antes de añadir como mix-in.',
   'Die Haferflocken rösten: Haferflocken in einer trockenen Pfanne bei mittlerer Hitze verteilen und häufig umrühren, 4–5 Minuten, bis sie duftend und goldbraun sind. Vor dem Hinzufügen als Mix-In abkühlen lassen.',
   'Torre a aveia em flocos: espalhe a aveia em flocos numa frigideira seca em fogo médio, mexendo com frequência, por 4–5 minutos até ficar aromática e dourada. Esfrie antes de adicioná-la como mix-in.',
   'Toasted oats add a nutty, granola-like depth.',
   'Les flocons d''avoine grillés apportent une profondeur de noisette, façon granola.',
   'Los copos de avena tostados aportan una profundidad de nuez, tipo granola.',
   'Geröstete Haferflocken geben eine nussige, granolaartige Tiefe.',
   'Aveia torrada acrescenta profundidade de noz, tipo granola.'),

-- 41. toast shredded coconut (coconut-macaroon)
  ('Toast the shredded coconut: spread shredded coconut on a dry skillet over medium heat, stirring frequently, for 3–4 minutes until golden. Transfer to a plate to cool.',
   'Griller la noix de coco râpée : étaler la noix de coco râpée dans une poêle sèche à feu moyen, en remuant fréquemment, pendant 3 à 4 minutes jusqu''à ce qu''elle soit dorée. Transférer sur une assiette pour refroidir.',
   'Tostar el coco rallado: extender el coco rallado en una sartén seca a fuego medio, removiendo con frecuencia, durante 3–4 minutos hasta que esté dorado. Transferir a un plato para enfriar.',
   'Die Kokosraspeln rösten: Kokosraspeln in einer trockenen Pfanne bei mittlerer Hitze verteilen und häufig umrühren, 3–4 Minuten, bis sie goldbraun sind. Zum Abkühlen auf einen Teller geben.',
   'Torre o coco ralado: espalhe o coco ralado numa frigideira seca em fogo médio, mexendo com frequência, por 3–4 minutos até ficar dourado. Transfira para um prato para esfriar.',
   'Coconut goes from golden to burnt fast — stir the whole time and pull it off while still pale.',
   'La noix de coco passe du doré au brûlé rapidement — remuez tout le temps et retirez-la tant qu''elle est encore pâle.',
   'El coco pasa de dorado a quemado rápidamente — remueve todo el tiempo y retíralo cuando todavía esté pálido.',
   'Kokos wird schnell von goldbraun zu verbrannt — die ganze Zeit umrühren und vom Herd nehmen, solange sie noch blass ist.',
   'O coco passa de dourado para queimado rapidamente — mexa o tempo todo e tire do fogo enquanto ainda estiver claro.'),

-- 42. bloom saffron (pistachio-saffron, with whisk)
  ('Bloom the saffron: warm 2 tablespoons of the milk and the saffron threads over low heat for 1 minute, then steep 10 minutes off heat. Whisk the bloomed saffron (threads and all) with the pistachio paste, remaining milk, cream, sugar, and vanilla extract until smooth and the sugar dissolves.',
   'Infuser le safran : faire chauffer 2 cuillères à soupe de lait avec les pistils de safran à feu doux pendant 1 minute, puis laisser infuser 10 minutes hors du feu. Fouetter le safran infusé (avec les pistils) avec la pâte de pistache, le reste du lait, la crème, le sucre et l''extrait de vanille jusqu''à ce que le mélange soit lisse et que le sucre soit dissous.',
   'Infusionar el azafrán: calentar 2 cucharadas de leche con las hebras de azafrán a fuego bajo durante 1 minuto, luego infusionar 10 minutos fuera del fuego. Batir el azafrán infusionado (con las hebras) con la pasta de pistacho, el resto de la leche, la nata, el azúcar y el extracto de vainilla hasta que esté suave y el azúcar se disuelva.',
   'Den Safran einziehen lassen: 2 Esslöffel Milch und die Safranfäden bei niedriger Hitze 1 Minute erwärmen, dann 10 Minuten vom Herd ziehen lassen. Den eingezogenen Safran (mit den Fäden) mit der Pistazienpaste, der restlichen Milch, der Sahne, dem Zucker und dem Vanilleextrakt verrühren, bis die Masse glatt ist und sich der Zucker gelöst hat.',
   'Ative o açafrão: aqueça 2 colheres de sopa de leite com os pistilos de açafrão em fogo baixo por 1 minuto, depois deixe em infusão por 10 minutos fora do fogo. Bata com fouet o açafrão ativado (com os pistilos) junto com a pasta de pistache, o restante do leite, o creme de leite, o açúcar e o extrato de baunilha até ficar liso e o açúcar dissolver.',
   'Saffron needs heat to release its color and flavor — do not skip the bloom.',
   'Le safran a besoin de chaleur pour libérer sa couleur et sa saveur — ne sautez pas l''étape d''infusion.',
   'El azafrán necesita calor para liberar su color y sabor — no saltes la infusión.',
   'Safran braucht Wärme, um seine Farbe und seinen Geschmack freizusetzen — den Einzieh-Schritt nicht überspringen.',
   'O açafrão precisa de calor para liberar cor e sabor — não pule a etapa de ativação.'),

-- 43. brown butter (brown-butter-cookie-dough)
  ('Brown the butter: melt butter in a small saucepan over medium heat, swirling until it turns amber and smells nutty (about 3 minutes). Pour into a heatproof bowl (including the brown bits at the bottom) and cool to room temperature. Whisk the cooled brown butter with the cream, milk, sugar, and vanilla extract until smooth and the sugar dissolves.',
   'Faire dorer le beurre : faire fondre le beurre dans une petite casserole à feu moyen, en remuant par mouvements circulaires jusqu''à ce qu''il prenne une couleur ambrée et dégage une odeur de noisette (environ 3 minutes). Verser dans un bol résistant à la chaleur (y compris les particules brunes au fond) et laisser refroidir à température ambiante. Fouetter le beurre noisette refroidi avec la crème, le lait, le sucre et l''extrait de vanille jusqu''à ce que le mélange soit lisse et que le sucre soit dissous.',
   'Dorar la mantequilla: derretir la mantequilla en un cazo pequeño a fuego medio, moviendo con movimientos circulares hasta que tome un color ámbar y huela a nuez (unos 3 minutos). Verter en un bol resistente al calor (incluyendo los trozos tostados del fondo) y dejar enfriar a temperatura ambiente. Batir la mantequilla noisette enfriada con la nata, la leche, el azúcar y el extracto de vainilla hasta que esté suave y el azúcar se disuelva.',
   'Die Butter bräunen: Butter in einem kleinen Topf bei mittlerer Hitze schmelzen, dabei schwenken, bis sie bernsteinfarben ist und nussig duftet (ca. 3 Minuten). In eine hitzefeste Schüssel gießen (einschließlich der braunen Teilchen am Boden) und auf Raumtemperatur abkühlen lassen. Die abgekühlte braune Butter mit der Sahne, der Milch, dem Zucker und dem Vanilleextrakt verrühren, bis die Masse glatt ist und sich der Zucker gelöst hat.',
   'Dourar a manteiga: derreta a manteiga numa panelinha em fogo médio, girando a panela até ficar âmbar e com aroma de noz (cerca de 3 minutos). Despeje numa tigela resistente ao calor (incluindo os resíduos tostados do fundo) e esfrie até temperatura ambiente. Bata com fouet a manteiga noisette resfriada junto com o creme de leite, o leite, o açúcar e o extrato de baunilha até ficar liso e o açúcar dissolver.',
   'The brown bits at the bottom carry most of the nutty flavor — do not strain them out.',
   'Les particules brunes au fond concentrent la plus grande partie de la saveur de noisette — ne les filtrez pas.',
   'Los trozos tostados del fondo concentran la mayor parte del sabor a nuez — no los cueles.',
   'Die braunen Teilchen am Boden tragen den größten Teil des nussigen Geschmacks — nicht absieben.',
   'Os resíduos tostados no fundo concentram a maior parte do sabor de noz — não coe.'),

-- 44. brown butter (vanilla-brown-butter, with whisk)
  ('Brown the butter: melt 3 tablespoons butter in a small saucepan over medium heat, swirling until amber and nutty-smelling (3 minutes). Pour into a heatproof bowl (including the brown bits) and cool to room temperature. Whisk the cooled brown butter with the cream, milk, sugar, vanilla extract, and sweetened condensed milk until smooth and the sugar dissolves.',
   'Faire dorer le beurre : faire fondre 3 cuillères à soupe de beurre dans une petite casserole à feu moyen, en remuant par mouvements circulaires jusqu''à ce qu''il soit ambré et qu''il dégage une odeur de noisette (3 minutes). Verser dans un bol résistant à la chaleur (y compris les particules brunes) et laisser refroidir à température ambiante. Fouetter le beurre noisette refroidi avec la crème, le lait, le sucre, l''extrait de vanille et le lait concentré sucré jusqu''à ce que le mélange soit lisse et que le sucre soit dissous.',
   'Dorar la mantequilla: derretir 3 cucharadas de mantequilla en un cazo pequeño a fuego medio, moviendo con movimientos circulares hasta que esté ámbar y huela a nuez (3 minutos). Verter en un bol resistente al calor (incluyendo los trozos tostados) y dejar enfriar a temperatura ambiente. Batir la mantequilla noisette enfriada con la nata, la leche, el azúcar, el extracto de vainilla y la leche condensada hasta que esté suave y el azúcar se disuelva.',
   'Die Butter bräunen: 3 Esslöffel Butter in einem kleinen Topf bei mittlerer Hitze schmelzen, dabei schwenken, bis sie bernsteinfarben und nussig duftet (3 Minuten). In eine hitzefeste Schüssel gießen (einschließlich der braunen Teilchen) und auf Raumtemperatur abkühlen lassen. Die abgekühlte braune Butter mit der Sahne, der Milch, dem Zucker, dem Vanilleextrakt und der gezuckerten Kondensmilch verrühren, bis die Masse glatt ist und sich der Zucker gelöst hat.',
   'Dourar a manteiga: derreta 3 colheres de sopa de manteiga numa panelinha em fogo médio, girando a panela até ficar âmbar e com aroma de noz (3 minutos). Despeje numa tigela resistente ao calor (incluindo os resíduos tostados) e esfrie até temperatura ambiente. Bata com fouet a manteiga noisette resfriada junto com o creme de leite, o leite, o açúcar, o extrato de baunilha e o leite condensado até ficar liso e o açúcar dissolver.',
   'Brown butter is the star — do not skip. Include all the toasted milk solids at the bottom.',
   'Le beurre noisette est la star — à ne pas sauter. Incluez toutes les particules de lait grillées au fond.',
   'La mantequilla noisette es la estrella — no la saltes. Incluye todos los sólidos lácteos tostados del fondo.',
   'Braune Butter ist der Star — nicht überspringen. Alle gerösteten Milchfeststoffe am Boden mitnehmen.',
   'A manteiga noisette é a estrela — não pule. Inclua todos os sólidos de leite tostados do fundo.'),

-- 45. brown butter + sage-pecan (brown-butter-sage-pecan)
  ('Brown the butter and infuse the sage: melt butter over medium heat, swirling until amber and nutty-smelling (3 minutes). Off heat, drop in the sage leaves and steep for 10 minutes, then strain out the leaves. Cool the sage-infused brown butter to room temperature. Whisk it with the cream, milk, sugar, vanilla extract, and sweetened condensed milk until smooth and the sugar dissolves.',
   'Faire dorer le beurre et infuser la sauge : faire fondre le beurre à feu moyen, en remuant par mouvements circulaires jusqu''à ce qu''il soit ambré et dégage une odeur de noisette (3 minutes). Hors du feu, ajouter les feuilles de sauge et laisser infuser 10 minutes, puis filtrer pour retirer les feuilles. Laisser refroidir le beurre noisette infusé à la sauge à température ambiante. Le fouetter avec la crème, le lait, le sucre, l''extrait de vanille et le lait concentré sucré jusqu''à ce que le mélange soit lisse et que le sucre soit dissous.',
   'Dorar la mantequilla e infusionar la salvia: derretir la mantequilla a fuego medio, moviendo con movimientos circulares hasta que esté ámbar y huela a nuez (3 minutos). Fuera del fuego, añadir las hojas de salvia e infusionar durante 10 minutos, luego colar para retirar las hojas. Dejar enfriar la mantequilla noisette infusionada con salvia a temperatura ambiente. Batirla con la nata, la leche, el azúcar, el extracto de vainilla y la leche condensada hasta que esté suave y el azúcar se disuelva.',
   'Die Butter bräunen und den Salbei einziehen lassen: Butter bei mittlerer Hitze schmelzen, dabei schwenken, bis sie bernsteinfarben ist und nussig duftet (3 Minuten). Vom Herd nehmen, die Salbeiblätter hineingeben und 10 Minuten ziehen lassen, dann die Blätter abseihen. Die salbei-infundierte braune Butter auf Raumtemperatur abkühlen lassen. Sie mit der Sahne, der Milch, dem Zucker, dem Vanilleextrakt und der gezuckerten Kondensmilch verrühren, bis die Masse glatt ist und sich der Zucker gelöst hat.',
   'Dourar a manteiga e infundir a sálvia: derreta a manteiga em fogo médio, girando a panela até ficar âmbar e com aroma de noz (3 minutos). Fora do fogo, adicione as folhas de sálvia e deixe em infusão por 10 minutos, depois coe para retirar as folhas. Esfrie a manteiga noisette infusionada com sálvia até temperatura ambiente. Bata com fouet junto com o creme de leite, o leite, o açúcar, o extrato de baunilha e o leite condensado até ficar liso e o açúcar dissolver.',
   'Brown butter + sage is a classic savoury combo that works beautifully in cream-based ice creams.',
   'Beurre noisette et sauge forment un duo salé classique qui fonctionne magnifiquement dans les crèmes glacées à base de crème.',
   'Mantequilla noisette y salvia son un dúo salado clásico que funciona magníficamente en helados a base de crema.',
   'Braune Butter + Salbei ist eine klassische herzhafte Kombination, die in sahnigen Eissorten wunderbar funktioniert.',
   'Manteiga noisette + sálvia é uma combinação clássica salgada que funciona lindamente em sorvetes cremosos.'),

-- 46. saffron-rose bloom
  ('Warm 2 tablespoons of the milk with the saffron threads in a small saucepan over low heat for 1 minute. Remove from heat and let steep for 10 minutes to bloom the saffron. Whisk the bloomed saffron (threads and all) with the rose water, remaining milk, cream, sugar, and vanilla extract until smooth and the sugar dissolves.',
   'Faire chauffer 2 cuillères à soupe de lait avec les pistils de safran dans une petite casserole à feu doux pendant 1 minute. Retirer du feu et laisser infuser 10 minutes pour libérer le safran. Fouetter le safran infusé (avec les pistils) avec l''eau de rose, le reste du lait, la crème, le sucre et l''extrait de vanille jusqu''à ce que le mélange soit lisse et que le sucre soit dissous.',
   'Calentar 2 cucharadas de leche con las hebras de azafrán en un cazo pequeño a fuego bajo durante 1 minuto. Retirar del fuego y dejar infusionar 10 minutos para liberar el azafrán. Batir el azafrán infusionado (con las hebras) con el agua de rosas, el resto de la leche, la nata, el azúcar y el extracto de vainilla hasta que esté suave y el azúcar se disuelva.',
   '2 Esslöffel Milch mit den Safranfäden in einem kleinen Topf bei niedriger Hitze 1 Minute erwärmen. Vom Herd nehmen und 10 Minuten ziehen lassen, damit der Safran sich entfaltet. Den eingezogenen Safran (mit den Fäden) mit dem Rosenwasser, der restlichen Milch, der Sahne, dem Zucker und dem Vanilleextrakt verrühren, bis die Masse glatt ist und sich der Zucker gelöst hat.',
   'Aqueça 2 colheres de sopa de leite com os pistilos de açafrão numa panelinha em fogo baixo por 1 minuto. Retire do fogo e deixe em infusão por 10 minutos para ativar o açafrão. Bata com fouet o açafrão ativado (com os pistilos) junto com a água de rosas, o restante do leite, o creme de leite, o açúcar e o extrato de baunilha até ficar liso e o açúcar dissolver.',
   'Saffron needs heat to release its aroma and color. Do not skip this bloom step — cold saffron tastes like nothing.',
   'Le safran a besoin de chaleur pour libérer son arôme et sa couleur. Ne sautez pas cette étape d''infusion — le safran froid n''a pas de goût.',
   'El azafrán necesita calor para liberar su aroma y color. No te saltes esta infusión — el azafrán frío no sabe a nada.',
   'Safran braucht Wärme, um sein Aroma und seine Farbe freizusetzen. Diesen Einzieh-Schritt nicht überspringen — kalter Safran schmeckt nach nichts.',
   'O açafrão precisa de calor para liberar aroma e cor. Não pule esta etapa de ativação — açafrão frio não tem sabor nenhum.'),

-- 47. persian-saffron bloom
  ('Bloom the saffron: warm 2 tablespoons of the milk in a small saucepan over low heat. Add the saffron threads and steep 10 minutes off heat. Whisk the bloomed saffron (threads and all) with the rose water, sweetened condensed milk, remaining milk, cream, sugar, and vanilla extract until smooth and the sugar dissolves.',
   'Infuser le safran : faire chauffer 2 cuillères à soupe de lait dans une petite casserole à feu doux. Ajouter les pistils de safran et laisser infuser 10 minutes hors du feu. Fouetter le safran infusé (avec les pistils) avec l''eau de rose, le lait concentré sucré, le reste du lait, la crème, le sucre et l''extrait de vanille jusqu''à ce que le mélange soit lisse et que le sucre soit dissous.',
   'Infusionar el azafrán: calentar 2 cucharadas de leche en un cazo pequeño a fuego bajo. Añadir las hebras de azafrán e infusionar 10 minutos fuera del fuego. Batir el azafrán infusionado (con las hebras) con el agua de rosas, la leche condensada, el resto de la leche, la nata, el azúcar y el extracto de vainilla hasta que esté suave y el azúcar se disuelva.',
   'Den Safran einziehen lassen: 2 Esslöffel Milch in einem kleinen Topf bei niedriger Hitze erwärmen. Die Safranfäden zufügen und 10 Minuten vom Herd ziehen lassen. Den eingezogenen Safran (mit den Fäden) mit dem Rosenwasser, der gezuckerten Kondensmilch, der restlichen Milch, der Sahne, dem Zucker und dem Vanilleextrakt verrühren, bis die Masse glatt ist und sich der Zucker gelöst hat.',
   'Ative o açafrão: aqueça 2 colheres de sopa de leite numa panelinha em fogo baixo. Adicione os pistilos de açafrão e deixe em infusão por 10 minutos fora do fogo. Bata com fouet o açafrão ativado (com os pistilos) junto com a água de rosas, o leite condensado, o restante do leite, o creme de leite, o açúcar e o extrato de baunilha até ficar liso e o açúcar dissolver.',
   'Persian saffron ice cream (bastani) should be pale gold with visible saffron flecks. Do not strain.',
   'La glace persane au safran (bastani) doit être d''un doré pâle avec des pistils de safran visibles. Ne pas filtrer.',
   'El helado persa de azafrán (bastani) debe ser de un dorado pálido con hebras de azafrán visibles. No colar.',
   'Persisches Safran-Eis (Bastani) sollte blassgolden mit sichtbaren Safranfäden sein. Nicht abseihen.',
   'O sorvete persa de açafrão (bastani) deve ser dourado claro com pistilos de açafrão visíveis. Não coe.');
